<?php
// Exit if accessed directly.
if (!defined('ABSPATH')) {
    exit;
}

/**
 * ====================================================================
 * INVOICE SYSTEM
 * ====================================================================
 * Free tier:  auto PDF invoice on order processing/completed, fixed
 *             sequential numbering, fixed "Generated by Coder Zone BD"
 *             footer, capped monthly count (local, not HQ-synced).
 * Pro tier:   custom numbering (prefix + reset period), BD tax fields,
 *             editable/removable footer, unlimited invoices.
 */

// Free-tier invoices are capped locally rather than via the HQ usage-sync
// system, since the invoice feature doesn't yet exist on the HQ side and
// cg_can_perform_action() fails closed when an action_type is unknown to it.
define('CG_FREE_INVOICE_MONTHLY_LIMIT', 20);

/**
 * Whether the Invoices module is enabled via the main Settings toggle.
 * Mirrors the enable_order_statuses convention used elsewhere in the plugin.
 *
 * @return bool
 */
function cg_invoices_enabled()
{
    $options = get_option('cg_plugin_options', []);
    return !empty($options['enable_invoices']);
}

/**
 * The dedicated, hidden order status used to back "blank" manual invoices
 * (Pro) that aren't tied to a real WooCommerce order.
 */
define('CG_MANUAL_INVOICE_STATUS', 'cg-manual-invoice');

/**
 * Registers the post status itself (needed so WordPress/WooCommerce know it
 * exists at all — e.g. for get_post_status_object() lookups), but with
 * 'show_in_admin_all_list' => false so it never appears in the WooCommerce
 * Orders list's default view. Deliberately excluded from the `wc_order_statuses`
 * filter — see cg_temporarily_register_manual_invoice_status() for why.
 *
 * This is separate from the user-configurable custom statuses in
 * order-statuses.php, which are intentionally exposed to WooCommerce.
 */
function cg_register_manual_invoice_order_status()
{
    register_post_status('wc-' . CG_MANUAL_INVOICE_STATUS, [
        'label'                     => _x('Manual Invoice', 'Order status', 'checkoutguard'),
        'public'                    => false,
        'exclude_from_search'       => true,
        'show_in_admin_all_list'    => false,
        'show_in_admin_status_list' => false,
        'internal'                  => true,
    ]);
}
add_action('init', 'cg_register_manual_invoice_order_status', 15);

/**
 * WC_Order::set_status() only accepts statuses present in
 * wc_get_order_statuses() (anything else silently falls back to "pending")
 * — so the status has to be momentarily added to that list purely for the
 * instant it's assigned. It's intentionally never added permanently: once
 * removed, it drops out of wc_get_order_statuses() again, which is what
 * keeps it out of every admin status dropdown, the Orders list, and
 * Analytics/reports revenue buckets (all of which key off that function) —
 * the order itself keeps the status string once saved regardless.
 *
 * @param callable $callback A callback that performs the status assignment.
 * @return mixed The callback's return value.
 */
function cg_with_manual_invoice_status_registered($callback)
{
    $inject = function ($statuses) {
        $statuses['wc-' . CG_MANUAL_INVOICE_STATUS] = _x('Manual Invoice', 'Order status', 'checkoutguard');
        return $statuses;
    };
    // Priority 999: cg_add_custom_statuses_to_woocommerce() (order-statuses.php,
    // priority 20) wholesale-replaces the statuses array, which would otherwise
    // discard this injected entry if added at a lower priority.
    add_filter('wc_order_statuses', $inject, 999);
    $result = $callback();
    remove_filter('wc_order_statuses', $inject, 999);
    return $result;
}

/**
 * Whether an order is a "blank" manual invoice (Pro) created without a real
 * WooCommerce order — i.e. purely a printable invoice/label record.
 *
 * @param WC_Order $order
 * @return bool
 */
function cg_is_manual_invoice_order($order)
{
    return $order instanceof WC_Order && $order->get_meta('_cg_manual_invoice', true);
}

/**
 * Registers the invoice settings option. Sanitization also re-enforces the
 * Pro gate server-side, so a Free-plan site can't unlock these fields by
 * posting directly to options.php.
 */
function cg_register_invoice_settings()
{
    register_setting('cg_invoice_settings_group', 'cg_invoice_settings', [
        'sanitize_callback' => 'cg_sanitize_invoice_settings',
    ]);
}
add_action('admin_init', 'cg_register_invoice_settings');

function cg_sanitize_invoice_settings($input)
{
    $input = is_array($input) ? $input : [];
    $is_pro = cg_is_pro_plan();

    $clean = [
        'number_digits'    => max(1, min(10, (int) ($input['number_digits'] ?? 6))),
        'company_name'     => isset($input['company_name']) ? sanitize_text_field($input['company_name']) : get_bloginfo('name'),
        'company_address'  => isset($input['company_address']) ? sanitize_textarea_field($input['company_address']) : '',
        'company_phone'    => isset($input['company_phone']) ? sanitize_text_field($input['company_phone']) : '',
        'company_email'    => isset($input['company_email']) ? sanitize_email($input['company_email']) : '',
        'company_logo_id'  => isset($input['company_logo_id']) ? absint($input['company_logo_id']) : 0,
        'footer_bg_color'  => isset($input['footer_bg_color']) && preg_match('/^#[0-9a-fA-F]{6}$/', $input['footer_bg_color']) ? $input['footer_bg_color'] : '#1e293b',
    ];

    if ($is_pro) {
        $clean['number_prefix']   = isset($input['number_prefix']) ? sanitize_text_field($input['number_prefix']) : 'INV-';
        // Resolve once: guarding only the in_array() check still leaves the
        // bare $input['number_reset'] read, which warns and stores null when
        // the field isn't submitted.
        $number_reset             = $input['number_reset'] ?? 'never';
        $clean['number_reset']    = in_array($number_reset, ['never', 'yearly', 'monthly'], true) ? $number_reset : 'never';
        $clean['show_tax_fields'] = !empty($input['show_tax_fields']);
        $clean['vat_reg_no']      = isset($input['vat_reg_no']) ? sanitize_text_field($input['vat_reg_no']) : '';
        $clean['tin_no']          = isset($input['tin_no']) ? sanitize_text_field($input['tin_no']) : '';
        $clean['bin_no']          = isset($input['bin_no']) ? sanitize_text_field($input['bin_no']) : '';
        $clean['footer_text']     = isset($input['footer_text']) ? sanitize_text_field($input['footer_text']) : '';
    }
    // On Free, Pro-only keys are simply omitted here — cg_get_invoice_settings()
    // always forces them back to their default/locked value on read regardless.

    return $clean;
}

/**
 * Returns invoice settings merged with defaults.
 * Pro-only fields are forced back to their default/locked value when the
 * site is not on a Pro plan, regardless of what's stored — this is the
 * server-side enforcement backstop for the UI-level gating.
 *
 * @return array
 */
function cg_get_invoice_settings()
{
    $defaults = [
        'footer_text'      => 'Generated by Coder Zone BD',
        'number_prefix'    => 'INV-',
        'number_digits'    => 6,
        'number_reset'     => 'never', // never|yearly|monthly (Pro only)
        'show_tax_fields'  => false,   // Pro only
        'vat_reg_no'       => '',
        'tin_no'           => '',
        'bin_no'           => '',
        'company_name'     => get_bloginfo('name'),
        'company_address'  => '',
        'company_phone'    => '',
        'company_email'    => get_option('admin_email'),
        'company_logo_id'  => 0,
        'footer_bg_color'  => '#1e293b',
    ];

    $stored = get_option('cg_invoice_settings', []);
    $settings = wp_parse_args(is_array($stored) ? $stored : [], $defaults);

    if (!cg_is_pro_plan()) {
        $settings['footer_text']     = $defaults['footer_text'];
        $settings['number_prefix']   = $defaults['number_prefix'];
        $settings['number_reset']    = 'never';
        $settings['show_tax_fields'] = false;
        $settings['vat_reg_no']      = '';
        $settings['tin_no']          = '';
        $settings['bin_no']          = '';
    }

    return $settings;
}

/**
 * Checks whether another invoice can be generated this month under the
 * free-tier cap. Always true on Pro.
 *
 * @return bool
 */
function cg_can_generate_invoice()
{
    if (cg_is_pro_plan()) {
        return true;
    }
    $bucket = 'cg_invoice_usage_' . gmdate('Y-m');
    $count = (int) get_option($bucket, 0);
    return $count < CG_FREE_INVOICE_MONTHLY_LIMIT;
}

/**
 * Increments the current month's free-tier invoice usage counter.
 */
function cg_increment_invoice_usage()
{
    if (cg_is_pro_plan()) {
        return;
    }
    $bucket = 'cg_invoice_usage_' . gmdate('Y-m');
    $count = (int) get_option($bucket, 0);
    update_option($bucket, $count + 1, false);
}

/**
 * Gets (assigning if necessary) the invoice number for an order.
 * Idempotent: once assigned, the same order always returns the same number.
 * Returns null if no invoice has been assigned and the free-tier cap is hit.
 *
 * @param WC_Order $order
 * @return string|null
 */
function cg_get_or_assign_invoice_number($order)
{
    if (!$order instanceof WC_Order) {
        return null;
    }

    $existing = $order->get_meta('_cg_invoice_number', true);
    if (!empty($existing)) {
        return $existing;
    }

    if (!cg_can_generate_invoice()) {
        return null;
    }

    $settings = cg_get_invoice_settings();

    // Determine the sequence bucket (Pro can reset yearly/monthly).
    $seq_key = 'cg_invoice_seq_all';
    if ($settings['number_reset'] === 'yearly') {
        $seq_key = 'cg_invoice_seq_' . gmdate('Y');
    } elseif ($settings['number_reset'] === 'monthly') {
        $seq_key = 'cg_invoice_seq_' . gmdate('Ym');
    }

    $next = (int) get_option($seq_key, 0) + 1;
    update_option($seq_key, $next, false);

    $digits = max(1, (int) $settings['number_digits']);
    $number = $settings['number_prefix'] . str_pad((string) $next, $digits, '0', STR_PAD_LEFT);

    $order->update_meta_data('_cg_invoice_number', $number);
    $order->update_meta_data('_cg_invoice_generated_at', current_time('mysql'));
    $order->save();

    cg_increment_invoice_usage();

    return $number;
}

/**
 * Renders the invoice HTML for an order. Shared by PDF generation.
 *
 * @param WC_Order $order
 * @param string   $invoice_number
 * @param bool     $is_packing_slip Omits all pricing (prices, totals) so the
 *                                  sheet can be packed with the goods.
 * @return string
 */
function cg_render_invoice_html($order, $invoice_number, $is_packing_slip = false)
{
    $settings = cg_get_invoice_settings();

    $store_name = get_bloginfo('name');
    $store_address = implode(', ', array_filter([
        get_option('woocommerce_store_address'),
        get_option('woocommerce_store_city'),
        get_option('woocommerce_store_postcode'),
    ]));

    ob_start();
    ?>
    <html>
    <head>
        <meta charset="utf-8">
        <style>
            body { font-family: DejaVu Sans, sans-serif; font-size: 12px; color: #1e293b; }
            .cg-inv-header { display: table; width: 100%; margin-bottom: 24px; }
            .cg-inv-header-col { display: table-cell; vertical-align: top; width: 50%; }
            .cg-inv-header-col.right { text-align: right; }
            h1 { font-size: 20px; margin: 0 0 4px 0; }
            .cg-inv-meta { color: #64748b; font-size: 11px; }
            table.cg-inv-items { width: 100%; border-collapse: collapse; margin-top: 16px; }
            table.cg-inv-items th { text-align: left; border-bottom: 2px solid #1e293b; padding: 6px 4px; font-size: 11px; text-transform: uppercase; }
            table.cg-inv-items td { border-bottom: 1px solid #e2e8f0; padding: 6px 4px; }
            .cg-inv-totals { width: 100%; margin-top: 12px; }
            .cg-inv-totals td { padding: 3px 4px; }
            .cg-inv-totals .label { text-align: right; color: #64748b; }
            .cg-inv-totals .value { text-align: right; width: 100px; }
            .cg-inv-totals .grand td { font-weight: bold; border-top: 2px solid #1e293b; font-size: 13px; }
            .cg-inv-tax { margin-top: 12px; font-size: 11px; color: #64748b; }
            .cg-inv-footer { margin-top: 40px; text-align: center; font-size: 10px; color: #94a3b8; }
        </style>
    </head>
    <body>
        <div class="cg-inv-header">
            <div class="cg-inv-header-col">
                <h1><?php echo esc_html($store_name); ?></h1>
                <?php if ($store_address): ?>
                    <div class="cg-inv-meta"><?php echo esc_html($store_address); ?></div>
                <?php endif; ?>
            </div>
            <div class="cg-inv-header-col right">
                <h1>Invoice</h1>
                <div class="cg-inv-meta">
                    <?php echo esc_html($invoice_number); ?><br>
                    Order #<?php echo esc_html($order->get_order_number()); ?><br>
                    <?php echo esc_html(date_i18n(get_option('date_format') . ' h:i:s A', $order->get_date_created() ? $order->get_date_created()->getTimestamp() : time())); ?>
                </div>
            </div>
        </div>

        <div>
            <strong>Billed to:</strong><br>
            <?php echo wp_kses_post($order->get_formatted_billing_address() ?: esc_html($order->get_formatted_billing_full_name())); ?><br>
            <?php if ($order->get_billing_phone()): ?><?php echo esc_html($order->get_billing_phone()); ?><br><?php endif; ?>
            <?php if ($order->get_billing_email()): ?><?php echo esc_html($order->get_billing_email()); ?><?php endif; ?>
        </div>

        <?php if ($settings['show_tax_fields'] && ($settings['vat_reg_no'] || $settings['tin_no'] || $settings['bin_no'])): ?>
        <div class="cg-inv-tax">
            <?php if ($settings['vat_reg_no']): ?>VAT Reg. No: <?php echo esc_html($settings['vat_reg_no']); ?><br><?php endif; ?>
            <?php if ($settings['tin_no']): ?>TIN: <?php echo esc_html($settings['tin_no']); ?><br><?php endif; ?>
            <?php if ($settings['bin_no']): ?>BIN: <?php echo esc_html($settings['bin_no']); ?><?php endif; ?>
        </div>
        <?php endif; ?>

        <table class="cg-inv-items">
            <thead>
                <tr>
                    <th>Item</th>
                    <th>Qty</th>
                    <?php if (!$is_packing_slip): ?>
                    <th>Price</th>
                    <th>Total</th>
                    <?php endif; ?>
                </tr>
            </thead>
            <tbody>
                <?php foreach ($order->get_items() as $item): ?>
                <tr>
                    <td><?php echo esc_html($item->get_name()); ?></td>
                    <td><?php echo esc_html($item->get_quantity()); ?></td>
                    <?php if (!$is_packing_slip): ?>
                    <td><?php echo wp_kses_post(wc_price($order->get_item_subtotal($item, false, true))); ?></td>
                    <td><?php echo wp_kses_post(wc_price($item->get_total())); ?></td>
                    <?php endif; ?>
                </tr>
                <?php endforeach; ?>
            </tbody>
        </table>

        <?php if (!$is_packing_slip): ?>
        <table class="cg-inv-totals">
            <tr><td class="label">Subtotal</td><td class="value"><?php echo wp_kses_post(wc_price($order->get_subtotal())); ?></td></tr>
            <?php if ((float) $order->get_shipping_total() > 0): ?>
            <tr><td class="label">Shipping</td><td class="value"><?php echo wp_kses_post(wc_price($order->get_shipping_total())); ?></td></tr>
            <?php endif; ?>
            <?php if ((float) $order->get_total_tax() > 0): ?>
            <tr><td class="label">Tax</td><td class="value"><?php echo wp_kses_post(wc_price($order->get_total_tax())); ?></td></tr>
            <?php endif; ?>
            <tr class="grand"><td class="label">Total</td><td class="value"><?php echo wp_kses_post(wc_price($order->get_total())); ?></td></tr>
        </table>
        <div class="cg-inv-meta" style="margin-top:8px;">Payment method: <?php echo esc_html($order->get_payment_method_title()); ?></div>
        <?php endif; ?>

        <?php if (!empty($settings['footer_text'])): ?>
        <div class="cg-inv-footer"><?php echo esc_html($settings['footer_text']); ?></div>
        <?php endif; ?>
    </body>
    </html>
    <?php
    return ob_get_clean();
}

/**
 * Generates the invoice PDF for an order and returns the raw PDF bytes.
 * Assigns an invoice number as a side effect if the order doesn't have one.
 *
 * @param WC_Order $order
 * @param bool     $is_packing_slip
 * @return string|WP_Error PDF binary content, or WP_Error if it couldn't be generated.
 */
function cg_generate_invoice_pdf($order, $is_packing_slip = false)
{
    if (!$order instanceof WC_Order) {
        return new WP_Error('cg_invoice_invalid_order', __('Invalid order.', 'checkoutguard'));
    }

    $number = cg_get_or_assign_invoice_number($order);
    if (!$number) {
        return new WP_Error(
            'cg_invoice_limit_reached',
            __('Monthly invoice limit reached on the Free plan. Upgrade to Pro for unlimited invoices.', 'checkoutguard')
        );
    }

    $autoload = CG_INC_DIR . 'vendor/autoload.php';
    if (!file_exists($autoload)) {
        return new WP_Error('cg_invoice_missing_lib', __('Invoice PDF library is missing.', 'checkoutguard'));
    }
    require_once $autoload;

    // dompdf's default font (DejaVu Sans) doesn't cover non-Latin currency
    // glyphs (e.g. ৳ for BDT), which render as missing-glyph boxes. Force the
    // ASCII currency code instead of the symbol for the duration of PDF HTML
    // rendering only — front-end/admin pages keep the normal symbol.
    $force_currency_code = function ($symbol) {
        // Spaces on both sides render as one in HTML regardless of whether
        // WooCommerce places the symbol before or after the amount.
        return ' ' . get_woocommerce_currency() . ' ';
    };
    add_filter('woocommerce_currency_symbol', $force_currency_code);
    $html = cg_render_invoice_html($order, $number, $is_packing_slip);
    remove_filter('woocommerce_currency_symbol', $force_currency_code);

    try {
        $dompdf = new \Dompdf\Dompdf([
            'isRemoteEnabled' => false,
            'isHtml5ParserEnabled' => true,
        ]);
        $dompdf->loadHtml($html);
        $dompdf->setPaper('A4');
        $dompdf->render();
        return $dompdf->output();
    } catch (\Throwable $e) {
        return new WP_Error('cg_invoice_render_failed', $e->getMessage());
    }
}

/**
 * Writes a generated invoice PDF to a temp file for use as an email
 * attachment (PHPMailer needs a filesystem path, not raw bytes).
 * Opportunistically cleans up stale temp invoice files older than 1 hour.
 *
 * @param WC_Order $order
 * @return string|WP_Error Temp file path, or WP_Error on failure.
 */
function cg_generate_invoice_pdf_tempfile($order)
{
    $pdf = cg_generate_invoice_pdf($order);
    if (is_wp_error($pdf)) {
        return $pdf;
    }

    $tmp_dir = untrailingslashit(get_temp_dir());

    // Opportunistic cleanup of stale invoice temp files.
    foreach (glob($tmp_dir . '/cg-invoice-*.pdf') ?: [] as $stale_file) {
        if (filemtime($stale_file) < time() - HOUR_IN_SECONDS) {
            @unlink($stale_file);
        }
    }

    $path = $tmp_dir . '/cg-invoice-' . $order->get_id() . '-' . wp_generate_password(8, false) . '.pdf';
    $written = file_put_contents($path, $pdf);
    if ($written === false) {
        return new WP_Error('cg_invoice_write_failed', __('Could not write invoice temp file.', 'checkoutguard'));
    }

    return $path;
}

/**
 * Auto-assigns an invoice number when an order reaches processing/completed.
 * The actual PDF is rendered on demand (download / email attachment) rather
 * than persisted to disk, so this hook only needs to ensure numbering happens
 * promptly (e.g. before the confirmation email fires).
 */
function cg_maybe_generate_invoice_on_status_change($order_id, $from_status, $to_status, $order)
{
    if (!in_array($to_status, ['processing', 'completed'], true)) {
        return;
    }
    if (!$order instanceof WC_Order) {
        $order = wc_get_order($order_id);
    }
    if ($order) {
        cg_get_or_assign_invoice_number($order);
    }
}
if (cg_invoices_enabled()) {
    add_action('woocommerce_order_status_changed', 'cg_maybe_generate_invoice_on_status_change', 20, 4);
}

/**
 * Attaches the invoice PDF to relevant customer order emails.
 */
function cg_attach_invoice_to_email($attachments, $email_id, $order, $email = null)
{
    $eligible_emails = ['customer_processing_order', 'customer_completed_order', 'customer_invoice'];
    if (!in_array($email_id, $eligible_emails, true) || !($order instanceof WC_Order)) {
        return $attachments;
    }

    // Only attach if an invoice number already exists or the free cap allows a new one.
    if (!$order->get_meta('_cg_invoice_number', true) && !cg_can_generate_invoice()) {
        return $attachments;
    }

    $path = cg_generate_invoice_pdf_tempfile($order);
    if (!is_wp_error($path)) {
        $attachments[] = $path;
    }

    return $attachments;
}
if (cg_invoices_enabled()) {
    add_filter('woocommerce_email_attachments', 'cg_attach_invoice_to_email', 10, 4);
}

/**
 * AJAX handler: streams the invoice PDF for download.
 * Accessible to logged-in admins (manage_woocommerce) and to the order's
 * own customer (matched by user ID, or by order key for guest checkouts).
 */
function cg_handle_download_invoice()
{
    if (!isset($_GET['order_id'], $_GET['nonce']) || !wp_verify_nonce(sanitize_key($_GET['nonce']), 'cg_download_invoice_' . intval($_GET['order_id']))) {
        wp_die(__('Security check failed.', 'checkoutguard'), '', ['response' => 403]);
    }

    $order_id = intval($_GET['order_id']);
    $order = wc_get_order($order_id);
    if (!$order) {
        wp_die(__('Order not found.', 'checkoutguard'), '', ['response' => 404]);
    }

    $can_access = current_user_can('manage_woocommerce');
    if (!$can_access && is_user_logged_in() && $order->get_customer_id() === get_current_user_id()) {
        $can_access = true;
    }
    if (!$can_access && !empty($_GET['key']) && hash_equals($order->get_order_key(), wp_unslash($_GET['key']))) {
        $can_access = true;
    }
    if (!$can_access) {
        wp_die(__('You do not have permission to access this invoice.', 'checkoutguard'), '', ['response' => 403]);
    }

    // Packing slip is a Pro feature — only admins/shop managers pack orders,
    // so no separate customer-facing access path is needed for it.
    $is_packing_slip = (($_GET['type'] ?? '') === 'packing_slip');
    if ($is_packing_slip && !cg_is_pro_plan()) {
        wp_die(__('Packing slips require a Pro plan.', 'checkoutguard'), '', ['response' => 403]);
    }

    $pdf = cg_generate_invoice_pdf($order, $is_packing_slip);
    if (is_wp_error($pdf)) {
        wp_die(esc_html($pdf->get_error_message()), '', ['response' => 500]);
    }

    $number = $order->get_meta('_cg_invoice_number', true);
    $suffix = $is_packing_slip ? '-packing-slip' : '';
    $filename = sanitize_file_name(($number ?: 'invoice-' . $order_id) . $suffix . '.pdf');

    nocache_headers();
    header('Content-Type: application/pdf');
    header('Content-Disposition: inline; filename="' . $filename . '"');
    header('Content-Length: ' . strlen($pdf));
    echo $pdf;
    exit;
}
if (cg_invoices_enabled()) {
    add_action('wp_ajax_cg_download_invoice', 'cg_handle_download_invoice');
    add_action('wp_ajax_nopriv_cg_download_invoice', 'cg_handle_download_invoice');
}

/**
 * Builds the (nonce-protected) invoice/packing-slip download URL for an order.
 *
 * @param WC_Order $order
 * @param bool     $packing_slip
 * @return string
 */
function cg_get_invoice_download_url($order, $packing_slip = false)
{
    $order_id = $order->get_id();
    $args = [
        'action'   => 'cg_download_invoice',
        'order_id' => $order_id,
        'nonce'    => wp_create_nonce('cg_download_invoice_' . $order_id),
    ];
    if ($packing_slip) {
        $args['type'] = 'packing_slip';
    }
    $url = add_query_arg($args, admin_url('admin-ajax.php'));

    // Allow guest customers (no account) to access via order key too.
    if (!is_user_logged_in()) {
        $url = add_query_arg('key', $order->get_order_key(), $url);
    }

    return $url;
}

/**
 * Renders the single invoice action link for an order. Only shown once an
 * invoice number has been assigned (i.e. the order reached
 * processing/completed).
 *
 * Admin (order edit screen / Invoices list): links to the interactive
 * Print page, which covers both the free Invoice view and the Pro-gated
 * shipping labels in one place — so only one button is ever needed there.
 *
 * Front-end (My Account): the Print page is a store fulfillment tool, not
 * something a customer needs, so this instead links straight to the plain
 * PDF invoice download.
 *
 * @param WC_Order $order
 */
function cg_render_invoice_download_link($order)
{
    if (!$order instanceof WC_Order || !$order->get_meta('_cg_invoice_number', true)) {
        return;
    }

    if (is_admin() && function_exists('cg_get_print_order_url')) {
        printf(
            '<a class="button cg-print-order" href="%s" target="_blank" rel="noopener">%s</a>',
            esc_url(cg_get_print_order_url($order->get_id())),
            esc_html__('Print Invoice', 'checkoutguard')
        );
        return;
    }

    printf(
        '<a class="button cg-download-invoice" href="%s" target="_blank" rel="noopener">%s</a>',
        esc_url(cg_get_invoice_download_url($order)),
        esc_html__('Download Invoice', 'checkoutguard')
    );
}

if (cg_invoices_enabled()) {
    // My Account → order view.
    add_action('woocommerce_order_details_after_order_table', 'cg_render_invoice_download_link', 20);

    // Admin order screen (classic + HPOS): show download link in the order actions area.
    add_action('woocommerce_admin_order_data_after_order_details', 'cg_render_invoice_download_link', 20);
}

