 * INVOICES ADMIN PAGE: list, manual generation, bulk download
 * ====================================================================
 */

/**
 * Fetches orders that have an invoice assigned, paginated and searchable.
 * Uses wc_get_orders() so this works correctly whether the store is on
 * legacy post-based orders or HPOS custom order tables.
 *
 * @param int    $page
 * @param int    $per_page
 * @param string $search
 * @return array{orders: WC_Order[], total: int, total_pages: int, page: int}
 */
function cg_fetch_invoiced_orders($page = 1, $per_page = 20, $search = '')
{
    $page = max(1, (int) $page);
    $per_page = max(1, min(100, (int) $per_page));

    $args = [
        'limit'        => $per_page,
        'page'         => $page,
        'orderby'      => 'date',
        'order'        => 'DESC',
        'meta_key'     => '_cg_invoice_number',
        'meta_compare' => 'EXISTS',
        'paginate'     => true,
        // wc_get_orders() defaults 'status' to only registered statuses, which
        // would silently exclude blank manual invoices (an intentionally
        // unregistered status — see CG_MANUAL_INVOICE_STATUS). Add it back in
        // explicitly; the meta_key filter above still does the real scoping.
        'status'       => array_merge(array_keys(wc_get_order_statuses()), ['wc-' . CG_MANUAL_INVOICE_STATUS]),
    ];

    $search = trim((string) $search);
    if ($search !== '') {
        // wc_get_orders() 's' searches billing name/email/phone and order number.
        $args['s'] = $search;
    }

    $result = wc_get_orders($args);

    return [
        'orders'      => $result->orders ?? [],
        'total'       => $result->total ?? 0,
        'total_pages' => $result->max_num_pages ?? 1,
        'page'        => $page,
    ];
}

/**
 * Creates a "blank" manual invoice (Pro): a fully isolated WC_Order — not
 * reachable via checkout, never affecting stock, never appearing in the
 * Orders list or sales reports (see cg_register_manual_invoice_order_status())
 * — built entirely from admin-entered data instead of a real purchase.
 * Line items may be freeform (product_id 0) or picked from the catalog;
 * either way they end up as normal WC_Order_Item_Product rows so every
 * existing invoice/print/label renderer works on the result unchanged.
 *
 * @param array $data {
 *   @type string $customer_name    Required.
 *   @type string $phone
 *   @type string $email
 *   @type string $address_1
 *   @type string $city
 *   @type string $state
 *   @type string $postcode
 *   @type string $country          Defaults to the store's base country.
 *   @type array  $items            Each: {product_id?, name, qty, price}. At least one required.
 *   @type float  $shipping_total
 *   @type string $payment_method   cod|paid|bank_transfer|other
 *   @type string $payment_method_title Optional custom label.
 *   @type string $transaction_id
 *   @type string $courier
 *   @type string $tracking_number
 * }
 * @return WC_Order|WP_Error
 */
function cg_create_manual_invoice_order($data)
{
    $name = trim((string) ($data['customer_name'] ?? ''));
    if ($name === '') {
        return new WP_Error('cg_missing_name', __('Customer name is required.', 'checkoutguard'));
    }

    $items = is_array($data['items'] ?? null) ? $data['items'] : [];
    $items = array_values(array_filter($items, function ($item) {
        return !empty($item['name']) && (float) ($item['qty'] ?? 0) > 0;
    }));
    if (empty($items)) {
        return new WP_Error('cg_missing_items', __('Add at least one line item.', 'checkoutguard'));
    }

    $order = cg_with_manual_invoice_status_registered(function () {
        return wc_create_order(['status' => CG_MANUAL_INVOICE_STATUS]);
    });
    if (is_wp_error($order)) {
        return $order;
    }

    $name_parts = explode(' ', $name, 2);
    $order->set_billing_first_name(sanitize_text_field($name_parts[0]));
    $order->set_billing_last_name(sanitize_text_field($name_parts[1] ?? ''));
    if (!empty($data['phone'])) {
        $order->set_billing_phone(sanitize_text_field($data['phone']));
    }
    if (!empty($data['email']) && is_email($data['email'])) {
        $order->set_billing_email(sanitize_email($data['email']));
    }
    if (!empty($data['address_1'])) {
        $order->set_billing_address_1(sanitize_text_field($data['address_1']));
    }
    if (!empty($data['city'])) {
        $order->set_billing_city(sanitize_text_field($data['city']));
    }
    if (!empty($data['state'])) {
        $order->set_billing_state(sanitize_text_field($data['state']));
    }
    if (!empty($data['postcode'])) {
        $order->set_billing_postcode(sanitize_text_field($data['postcode']));
    }
    $order->set_billing_country(!empty($data['country']) ? sanitize_text_field($data['country']) : WC()->countries->get_base_country());
    $order->set_currency(get_woocommerce_currency());

    foreach ($items as $item_data) {
        $qty = max(1, (int) $item_data['qty']);
        $price = max(0, (float) ($item_data['price'] ?? 0));
        $line_total = round($price * $qty, wc_get_price_decimals());

        $item = new WC_Order_Item_Product();
        $item->set_name(sanitize_text_field($item_data['name']));
        $item->set_quantity($qty);
        $item->set_subtotal($line_total);
        $item->set_total($line_total);

        if (!empty($item_data['product_id'])) {
            $product = wc_get_product((int) $item_data['product_id']);
            if ($product) {
                if ($product->is_type('variation')) {
                    $item->set_product_id($product->get_parent_id());
                    $item->set_variation_id($product->get_id());
                } else {
                    $item->set_product_id($product->get_id());
                }
            }
        }
        $order->add_item($item);
    }

    $shipping_total = max(0, (float) ($data['shipping_total'] ?? 0));
    if ($shipping_total > 0) {
        $shipping_item = new WC_Order_Item_Shipping();
        $shipping_item->set_method_title(__('Shipping', 'checkoutguard'));
        $shipping_item->set_total($shipping_total);
        $order->add_item($shipping_item);
    }

    $default_titles = [
        'cod'           => __('Cash on Delivery', 'checkoutguard'),
        'paid'          => __('Paid', 'checkoutguard'),
        'bank_transfer' => __('Bank Transfer', 'checkoutguard'),
        'other'         => __('Other', 'checkoutguard'),
    ];
    $payment_method = isset($default_titles[$data['payment_method'] ?? '']) ? $data['payment_method'] : 'other';
    $payment_title = !empty($data['payment_method_title']) ? sanitize_text_field($data['payment_method_title']) : $default_titles[$payment_method];

    $order->set_payment_method($payment_method);
    $order->set_payment_method_title($payment_title);
    if (!empty($data['transaction_id'])) {
        $order->set_transaction_id(sanitize_text_field($data['transaction_id']));
    }
    if ($payment_method === 'paid') {
        $order->set_date_paid(time());
    }

    $order->update_meta_data('_cg_manual_invoice', 1);
    if (!empty($data['courier'])) {
        $order->update_meta_data('_cg_courier', sanitize_text_field($data['courier']));
    }
    if (!empty($data['tracking_number'])) {
        $order->update_meta_data('_cg_tracking_number', sanitize_text_field($data['tracking_number']));
    }

    $order->calculate_totals(false);
    $order->save();

    return $order;
}

/**
 * AJAX handler: generates an invoice either for an existing order (Free +
 * Pro), or as a brand-new "blank" manual invoice with no underlying order
 * (Pro only — see cg_create_manual_invoice_order()).
 */
function cg_handle_generate_manual_invoice_ajax()
{
    check_ajax_referer('cg_invoices_nonce', 'nonce');
    if (!current_user_can('manage_woocommerce')) {
        wp_send_json_error(['message' => __('Permission denied.', 'checkoutguard')]);
        return;
    }

    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0;

    if ($order_id) {
        $order = wc_get_order($order_id);
        if (!$order) {
            wp_send_json_error(['message' => __('Order not found.', 'checkoutguard')]);
            return;
        }

        if ($order->get_meta('_cg_invoice_number', true)) {
            wp_send_json_error(['message' => __('This order already has an invoice.', 'checkoutguard')]);
            return;
        }

        $number = cg_get_or_assign_invoice_number($order);
        if (!$number) {
            wp_send_json_error(['message' => __('Could not generate invoice number.', 'checkoutguard')]);
            return;
        }

        wp_send_json_success([
            'message'        => sprintf(__('Invoice %s generated.', 'checkoutguard'), $number),
            'invoice_number' => $number,
            'download_url'   => cg_get_invoice_download_url($order),
            'print_url'      => function_exists('cg_get_print_order_url') ? cg_get_print_order_url($order->get_id()) : '',
        ]);
        return;
    }

    // No order_id: this is a blank manual invoice — Pro only.
    if (!cg_is_pro_plan()) {
        wp_send_json_error(['message' => __('Creating a blank manual invoice requires a Pro plan.', 'checkoutguard')], 403);
        return;
    }

    $raw_items = isset($_POST['items']) ? (array) $_POST['items'] : [];
    $items = [];
    foreach ($raw_items as $raw_item) {
        if (!is_array($raw_item)) {
            continue;
        }
        $items[] = [
            'product_id' => isset($raw_item['product_id']) ? absint($raw_item['product_id']) : 0,
            'name'       => isset($raw_item['name']) ? sanitize_text_field(wp_unslash($raw_item['name'])) : '',
            'qty'        => isset($raw_item['qty']) ? (int) $raw_item['qty'] : 0,
            'price'      => isset($raw_item['price']) ? (float) $raw_item['price'] : 0,
        ];
    }

    $data = [
        'customer_name'        => sanitize_text_field(wp_unslash($_POST['customer_name'] ?? '')),
        'phone'                => sanitize_text_field(wp_unslash($_POST['phone'] ?? '')),
        'email'                => sanitize_text_field(wp_unslash($_POST['email'] ?? '')),
        'address_1'            => sanitize_text_field(wp_unslash($_POST['address_1'] ?? '')),
        'city'                 => sanitize_text_field(wp_unslash($_POST['city'] ?? '')),
        'state'                => sanitize_text_field(wp_unslash($_POST['state'] ?? '')),
        'postcode'             => sanitize_text_field(wp_unslash($_POST['postcode'] ?? '')),
        'country'              => sanitize_text_field(wp_unslash($_POST['country'] ?? '')),
        'items'                => $items,
        'shipping_total'       => isset($_POST['shipping_total']) ? (float) $_POST['shipping_total'] : 0,
        'payment_method'       => sanitize_key($_POST['payment_method'] ?? 'other'),
        'payment_method_title' => sanitize_text_field(wp_unslash($_POST['payment_method_title'] ?? '')),
        'transaction_id'       => sanitize_text_field(wp_unslash($_POST['transaction_id'] ?? '')),
        'courier'              => sanitize_text_field(wp_unslash($_POST['courier'] ?? '')),
        'tracking_number'      => sanitize_text_field(wp_unslash($_POST['tracking_number'] ?? '')),
    ];

    $order = cg_create_manual_invoice_order($data);
    if (is_wp_error($order)) {
        wp_send_json_error(['message' => $order->get_error_message()]);
        return;
    }

    $number = cg_get_or_assign_invoice_number($order);
    if (!$number) {
        wp_send_json_error(['message' => __('Could not generate invoice number.', 'checkoutguard')]);
        return;
    }

    wp_send_json_success([
        'message'        => sprintf(__('Invoice %s created.', 'checkoutguard'), $number),
        'invoice_number' => $number,
        'download_url'   => cg_get_invoice_download_url($order),
        'print_url'      => function_exists('cg_get_print_order_url') ? cg_get_print_order_url($order->get_id()) : '',
    ]);
}
if (cg_invoices_enabled()) {
    add_action('wp_ajax_cg_generate_manual_invoice', 'cg_handle_generate_manual_invoice_ajax');
}

/**
 * AJAX handler: returns a picked product's name + price, used by the New
 * Blank Invoice modal's product picker to autofill a line item (WooCommerce's
 * own product-search endpoint only returns a display label, not raw price).
 */
function cg_handle_get_product_info_ajax()
{
    check_ajax_referer('cg_invoices_nonce', 'nonce');
    if (!current_user_can('manage_woocommerce')) {
        wp_send_json_error(['message' => __('Permission denied.', 'checkoutguard')]);
        return;
    }

    $product_id = isset($_POST['product_id']) ? absint($_POST['product_id']) : 0;
    $product = $product_id ? wc_get_product($product_id) : false;
    if (!$product) {
        wp_send_json_error(['message' => __('Product not found.', 'checkoutguard')]);
        return;
    }

    wp_send_json_success([
        'name'  => $product->get_name(),
        'price' => (float) wc_get_price_excluding_tax($product),
    ]);
}
if (cg_invoices_enabled()) {
    add_action('wp_ajax_cg_get_product_info', 'cg_handle_get_product_info_ajax');
}

/**
 * AJAX handler: fetches a page of the invoices list as rendered HTML,
 * for the Invoices admin page's search/pagination.
 */
function cg_handle_fetch_invoices_ajax()
{
    check_ajax_referer('cg_invoices_nonce', 'nonce');
    if (!current_user_can('manage_woocommerce')) {
        wp_send_json_error(['message' => __('Permission denied.', 'checkoutguard')]);
        return;
    }

    $page = isset($_POST['page']) ? max(1, intval($_POST['page'])) : 1;
    $search = isset($_POST['search']) ? sanitize_text_field(wp_unslash($_POST['search'])) : '';

    $result = cg_fetch_invoiced_orders($page, 20, $search);

    wp_send_json_success([
        'html'        => cg_get_invoices_table_rows_html($result['orders']),
        'total'       => $result['total'],
        'total_pages' => $result['total_pages'],
        'page'        => $result['page'],
    ]);
}
if (cg_invoices_enabled()) {
    add_action('wp_ajax_cg_fetch_invoices', 'cg_handle_fetch_invoices_ajax');
}

/**
 * AJAX handler: bundles the selected orders' invoice PDFs into a ZIP and
 * returns it base64-encoded for client-side Blob download (mirrors the
 * existing CSV blocklist export pattern). Pro-only.
 */
function cg_handle_bulk_download_invoices_ajax()
{
    check_ajax_referer('cg_invoices_nonce', 'nonce');
    if (!current_user_can('manage_woocommerce')) {
        wp_send_json_error(['message' => __('Permission denied.', 'checkoutguard')]);
        return;
    }
    if (!cg_is_pro_plan()) {
        wp_send_json_error(['message' => __('Bulk invoice download requires a Pro plan.', 'checkoutguard')], 403);
        return;
    }

    $order_ids = isset($_POST['order_ids']) ? array_map('intval', (array) $_POST['order_ids']) : [];
    $order_ids = array_slice(array_filter($order_ids), 0, 100);
    if (empty($order_ids)) {
        wp_send_json_error(['message' => __('No invoices selected.', 'checkoutguard')]);
        return;
    }

    if (!class_exists('ZipArchive')) {
        wp_send_json_error(['message' => __('The PHP zip extension is required for bulk download.', 'checkoutguard')]);
        return;
    }

    $zip_path = untrailingslashit(get_temp_dir()) . '/cg-invoices-' . wp_generate_password(8, false) . '.zip';
    $zip = new ZipArchive();
    if ($zip->open($zip_path, ZipArchive::CREATE | ZipArchive::OVERWRITE) !== true) {
        wp_send_json_error(['message' => __('Could not create ZIP file.', 'checkoutguard')]);
        return;
    }

    $added = 0;
    foreach ($order_ids as $order_id) {
        $order = wc_get_order($order_id);
        if (!$order) {
            continue;
        }
        $pdf = cg_generate_invoice_pdf($order);
        if (is_wp_error($pdf)) {
            continue;
        }
        $number = $order->get_meta('_cg_invoice_number', true) ?: ('invoice-' . $order_id);
        $zip->addFromString(sanitize_file_name($number) . '.pdf', $pdf);
        $added++;
    }
    $zip->close();

    if ($added === 0) {
        @unlink($zip_path);
        wp_send_json_error(['message' => __('No invoices could be generated for the selected orders.', 'checkoutguard')]);
        return;
    }

    $zip_content = file_get_contents($zip_path);
    @unlink($zip_path);

    wp_send_json_success([
        'zip_base64' => base64_encode($zip_content),
        'filename'   => 'checkoutguard-invoices-' . gmdate('Y-m-d') . '.zip',
        'count'      => $added,
    ]);
}
if (cg_invoices_enabled()) {
    add_action('wp_ajax_cg_bulk_download_invoices', 'cg_handle_bulk_download_invoices_ajax');
}
